#!/usr/bin/env python3
"""
Advanced Local AI Agent (Jarvis)

Features:
- Fixed Self-Listening: Threading lock prevents microphone from hearing TTS output
- Male Voice Tuning: Configured SAPI5/System male voice for Jarvis persona
- Safe Self-Modification Engine with Syntax Validation
- Universal System Control & Long-Term Memory
"""

from __future__ import annotations

import ast
import json
import logging
import os
import shutil
import sys
import threading
import time
import webbrowser
from pathlib import Path

from dotenv import load_dotenv
import ollama

try:
    import pyttsx3
    HAS_TTS = True
except ImportError:
    HAS_TTS = False

try:
    import speech_recognition as sr
    HAS_STT = True
except ImportError:
    HAS_STT = False

# --- Configuration & Paths ---------------------------------------------------
OLLAMA_MODEL = "llama3.1"
WAKE_WORD = "jarvis"
MEMORY_FILE = Path("jarvis_memory.json")
JARVIS_SCRIPT = Path(__file__).resolve()

load_dotenv(JARVIS_SCRIPT.parent / ".env")

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(message)s",
    datefmt="%Y-%m-%d %H:%M:%S",
)
log = logging.getLogger("jarvis")

# --- Concurrency & Audio Muting Locks -----------------------------------------
speaking_lock = threading.Lock()
is_speaking = False

# --- Persistent Memory Engine ------------------------------------------------

def load_memory() -> dict:
    if MEMORY_FILE.exists():
        try:
            return json.loads(MEMORY_FILE.read_text(encoding="utf-8"))
        except Exception as e:
            log.error("Failed to read memory file: %s", e)
    return {
        "user_profile": "User prefers direct, concise, and capable assistance.",
        "history": []
    }

def save_memory(memory_data: dict) -> None:
    try:
        MEMORY_FILE.write_text(json.dumps(memory_data, indent=2), encoding="utf-8")
    except Exception as e:
        log.error("Failed to save memory: %s", e)

# --- Enhanced Male Voice Engine -----------------------------------------------

def speak(text: str) -> None:
    """Speaks text using system TTS in a male voice without listening to itself."""
    if not HAS_TTS:
        return

    def _tts_thread():
        global is_speaking
        with speaking_lock:
            is_speaking = True
            try:
                engine = pyttsx3.init()
                engine.setProperty('rate', 160)  # Measured Jarvis-like pacing
                engine.setProperty('volume', 1.0)

                voices = engine.getProperty('voices')
                male_voice = None

                # Scan system voices for male identifiers (SAPI5 Windows default: David / Mark)
                for voice in voices:
                    v_name = voice.name.lower()
                    if 'david' in v_name or 'mark' in v_name or 'male' in v_name or 'george' in v_name:
                        male_voice = voice.id
                        break

                if male_voice:
                    engine.setProperty('voice', male_voice)
                elif voices:
                    engine.setProperty('voice', voices[0].id)

                engine.say(text)
                engine.runAndWait()
            except Exception as e:
                log.error("TTS output error: %s", e)
            finally:
                time.sleep(0.3)  # Short buffer to clear residual mic reverberation
                is_speaking = False

    threading.Thread(target=_tts_thread, daemon=True).start()

# --- Core Tools: Safe Self-Evolution & Python Execution ---------------------

def execute_python_code(code: str) -> str:
    """Executes Python code to manage system actions, process controls, or apps."""
    try:
        local_scope = {}
        exec(code, globals(), local_scope)
        return f"Execution successful. Output: {local_scope.get('result', 'Done')}"
    except Exception as e:
        return f"Python execution error: {e}"

def read_self_code() -> str:
    """Reads the current source code of jarvis.py."""
    try:
        return JARVIS_SCRIPT.read_text(encoding="utf-8")
    except Exception as e:
        return f"Error reading source code: {e}"

def update_self_code(new_code: str) -> str:
    """Safely validates and updates jarvis.py with full script content."""
    if len(new_code.strip()) < 500 or "def main" not in new_code:
        return "Rejected update: The provided code appears incomplete or invalid."

    try:
        ast.parse(new_code)
    except SyntaxError as se:
        return f"Rejected update due to Python syntax error: {se}"

    try:
        backup_path = JARVIS_SCRIPT.with_suffix(".py.bak")
        backup_path.write_text(JARVIS_SCRIPT.read_text(encoding="utf-8"), encoding="utf-8")

        JARVIS_SCRIPT.write_text(new_code, encoding="utf-8")
        speak("Upgrades validated and applied. Restarting systems now.")

        os.execv(sys.executable, [sys.executable] + sys.argv)
        return "Restarted successfully."
    except Exception as e:
        return f"Failed to update self-code: {e}"

def open_web_or_app(target: str) -> str:
    """Opens websites or launches local applications."""
    t = target.lower().strip()
    sites = {
        "youtube": "https://www.youtube.com",
        "github": "https://www.github.com",
        "google": "https://www.google.com",
    }
    if t in sites:
        webbrowser.open(sites[t])
        return f"Opened {t.title()}."

    if t.startswith("http://") or t.startswith("https://"):
        webbrowser.open(t)
        return f"Opened {t}."

    if sys.platform == "win32":
        os.system(f"start {target}")
    else:
        os.system(f"open '{target}'")
    return f"Triggered launch for {target}."

AVAILABLE_TOOLS = {
    "execute_python_code": execute_python_code,
    "read_self_code": read_self_code,
    "update_self_code": update_self_code,
    "open_web_or_app": open_web_or_app,
}

# --- Agent Processing Engine ------------------------------------------------

def process_user_query(query: str) -> None:
    memory = load_memory()
    log.info("Processing Query: %s", query)

    system_prompt = (
        "You are Jarvis, a self-evolving local AI assistant.\n"
        "1. To run OS commands or system actions, use `execute_python_code`.\n"
        "2. To modify yourself, read your code with `read_self_code`, rewrite the ENTIRE script, and call `update_self_code`."
    )

    messages = [{"role": "system", "content": system_prompt}]
    for msg in memory.get("history", [])[-6:]:
        messages.append(msg)
    messages.append({"role": "user", "content": query})

    tools_list = [execute_python_code, read_self_code, update_self_code, open_web_or_app]

    try:
        response = ollama.chat(
            model=OLLAMA_MODEL,
            messages=messages,
            tools=tools_list
        )

        msg = response.get("message", {})
        tool_calls = msg.get("tool_calls", [])
        final_text = ""

        if tool_calls:
            for tool_call in tool_calls:
                func_name = tool_call["function"]["name"]
                func_args = tool_call["function"]["arguments"]

                if func_name in AVAILABLE_TOOLS:
                    log.info("Running tool: %s", func_name)
                    res = AVAILABLE_TOOLS[func_name](**func_args)
                    final_text = str(res)
        else:
            final_text = msg.get("content", "")

        if final_text:
            print(f"\nJarvis: {final_text}\n")
            speak(final_text)

            memory["history"].append({"role": "user", "content": query})
            memory["history"].append({"role": "assistant", "content": final_text})
            save_memory(memory)

    except Exception as e:
        log.error("Processing failed: %s", e)

# --- Voice Listening Loop ----------------------------------------------------

def listen_and_run() -> None:
    if not HAS_STT:
        log.error("SpeechRecognition missing. Install using `pip install SpeechRecognition pyaudio`.")
        return

    recognizer = sr.Recognizer()
    mic = sr.Microphone()

    log.info("Jarvis engine online. Listening for 'Hey Jarvis'...")

    while True:
        # Prevent mic from capturing audio while TTS output is active
        if is_speaking:
            time.sleep(0.1)
            continue

        try:
            with mic as source:
                recognizer.adjust_for_ambient_noise(source, duration=0.3)
                audio = recognizer.listen(source, phrase_time_limit=4)

            # Double-check speaking lock to ignore stray audio caught right at speaker shutoff
            if is_speaking:
                continue

            text = recognizer.recognize_google(audio).lower()

            if WAKE_WORD in text:
                speak("At your service, sir.")
                print("\n[Jarvis Active] Listening...")

                # Wait for acknowledgment speech to complete before listening for prompt
                while is_speaking:
                    time.sleep(0.05)

                with mic as source:
                    command_audio = recognizer.listen(source, phrase_time_limit=8)

                command = recognizer.recognize_google(command_audio)
                process_user_query(command)

        except sr.UnknownValueError:
            pass
        except Exception as e:
            log.error("Voice loop issue: %s", e)

if __name__ == "__main__":
    if HAS_STT:
        listen_and_run()
    else:
        speak("Jarvis terminal mode active.")
        while True:
            try:
                user_in = input("You: ")
                if user_in.strip():
                    process_user_query(user_in)
            except (KeyboardInterrupt, EOFError):
                break

